int n = 2;
switch (n) {
    case 1: printf("one ");
    case 2: printf("two ");
    case 3: printf("three ");
    default: printf("other");
}

for (i = 1; i <= 10; i++) {
    if (i % 3 == 0) continue;
    if (i == 8) break;
    printf("%d ", i);
}

void addTen(int x) {
    x = x + 10;
}
int main() {
    int n = 5;
    addTen(n);
    printf("%d", n);   /* prints 5 */
}

class Person:
    def __init__(self, name):
        self.name = name
class Student(Person):
    def greet(self):
        return "Hi " + self.name
s = Student("Ali")
print(s.greet())        # Hi Ali
